	[947] = {
		name = "아제로스",
		short = "만 년 전, 영원의 샘이 지닌 힘에 도취된 칼림도어의 명가는 타락한 티탄 살게라스의 부름에 응하여 불타는 군단을 위한 문을 열어젖혔다.",
		full = "만 년 전, 영원의 샘이 지닌 힘에 도취된 칼림도어의 명가는 타락한 티탄 살게라스의 부름에 응하여 불타는 군단을 위한 문을 열어젖혔다. 말퓨리온 스톰레이지와 칼도레이 저항군은 용의 영혼으로 그 문을 부수고 살게라스를 뒤틀린 황천으로 몰아냈지만, 샘의 붕괴는 세계 그 자체를 부숴 놓았다. 고대 칼림도어는 불길과 홍수 속에 가라앉았다. 잔해 위로 폐허가 된 대륙들이 솟아올랐고, 물에 잠긴 대지의 심장부는 대해가 되었으며, 샘이 있던 자리에는 혼돈의 소용돌이가 휘몰아치게 되었다.",
