	[1411] = {
		name = "듀로타",
		short = "듀로타는 바위산과 협곡이 이어지는 갈라진 붉은 땅으로, 메마르고 뜨거우며 물도 푸른 것도 드물다.",
		full = "듀로타는 바위산과 협곡이 이어지는 갈라진 붉은 땅으로, 메마르고 뜨거우며 물도 푸른 것도 드물다. 오크들은 이곳에서 드레노어를 떠올리게 하는 거친 아름다움을 발견한다. 하이잘 산의 전투가 끝난 뒤 스랄은 바로 이곳으로 동족을 이끌어 새 고향을 세웠고, 살해당한 아버지 듀로탄의 이름을 따서 이 땅의 이름을 지었다. 본래 이 땅은 서슬갈기 가시멧돼지의 것이었으나 호드가 그들을 몰아냈다.\n\n그 평화는 오래가지 못했다. 2차 대전쟁의 영웅이자 오크에게 결코 호의적이지 않았던 대제독 데일린 프라우드무어가 호드가 뿌리내리기 전에 짓밟겠다며 얼라이언스의 대함대를 이끌고 듀로타로 쳐들어왔다. 그의 딸 제이나는 다른 길을 택했다. 테라모어에서 그녀는 아버지에게 등을 돌리고 스랄의 편에서 싸웠으며, 데일린은 두 사람이 화해하기도 전에 전투에서 목숨을 잃었다. 스랄은 그녀의 신의에 감사하며 제이나의 병사들이 무사히 테라모어로 물러나도록 허락했다.\n\n검은창 트롤은 스스로 원해서가 아니라 추방자로서 듀로타의 해안에 왔다. 동족인 주술사 잘라제인에게 배신당한 그들은 메아리 섬의 보금자리에서 쫓겨나 본토 해안에 어촌인 센진 마을을 세웠고, 잘라제인이 빼앗아 간 것을 끝내 되찾지 못했다.",
		source = "https://warcraft.wiki.gg/wiki/Durotar_(Classic)",
	},
	[1412] = {
		name = "멀고어",
		short = "수백 년 동안 타우렌에게는 자신들의 땅이 없었다. 켄타우로스 약탈자들에게 쫓겨 칼림도어 곳곳을 떠돌았고, 부족들은 흩어져 떠도는 야영지 신세가 되었다.",
		full = "수백 년 동안 타우렌에게는 자신들의 땅이 없었다. 켄타우로스 약탈자들에게 쫓겨 칼림도어 곳곳을 떠돌았고, 부족들은 흩어져 떠도는 야영지 신세가 되었다. 스랄과 오크들이 이 해안에 상륙했을 때, 케른 블러드후프는 그들에게서 명예롭고 강인한 동류의 영혼을 보았다. 오크들의 호위와 힘을 등에 업은 케른은 사방이 산으로 둘러싸인 아늑한 골짜기로 동족을 이끌었고, 그곳에서 블러드후프 부족은 초원에서 켄타우로스를 몰아내고 마침내 그 땅을 차지했다.\n\n케른은 평원 위로 솟은 고원 위에 썬더 블러프를 세웠다. 그곳은 모든 부족의 타우렌에게 열린 안식처였고, 시간이 흘러 흩어져 있던 부족들은 그의 통치 아래 하나로 뭉쳤다.\n\n목초지는 여전히 푸르고, 고원들은 지금도 블러드후프 마을 위로 긴 그림자를 드리운다. 성년이 된 타우렌은 누구나 조상들이 그러했듯 거친 평원으로 나아가 위대한 사냥에서 스스로를 증명해야 한다.",
		source = "https://warcraft.wiki.gg/wiki/Mulgore_(Classic)",
