	[1413] = {
		name = "불모의 땅",
		short = "이곳의 흙먼지가 처음부터 흙먼지였던 것은 아니다. 한때 이곳은 칼도레이가 가꾸던 숲이었고, 그들은 이곳에 텐랄로어 전초기지를 세웠다. 고대의 전쟁 때 반신 로고쉬가 이곳에서 불타는 군단에 맞섰다고 전해진다.",
		full = "이곳의 흙먼지가 처음부터 흙먼지였던 것은 아니다. 한때 이곳은 칼도레이가 가꾸던 숲이었고, 그들은 이곳에 텐랄로어 전초기지를 세웠다. 고대의 전쟁 때 반신 로고쉬가 이곳에서 불타는 군단에 맞섰다고 전해진다. 대분리가 그 모든 것을 끝냈고, 푸른 골짜기는 지금처럼 햇볕에 그을린 평원이 되었다.\n\n여러 세대 동안 타우렌은 이 평원을 떠돌며 코도와 천둥도마뱀을 사냥하고 대지 어머니의 지혜를 구했지만, 재미 삼아 그들을 사냥하는 켄타우로스에게 늘 쫓겨 다녔다. 그들은 맞서 싸웠으나 결코 전쟁이 좋아서 싸운 것은 아니었다. 켄타우로스가 몰려오면 목숨을 헛되이 버리기보다 천막을 걷고 떠나는 쪽을 택했다. 평화의 한 해, 전쟁의 한 해. 그것이 타우렌의 삶이었다. 스랄의 오크와 검은창 트롤이 상륙하여 블러드후프 타우렌과 함께 켄타우로스에 맞서 진군하기 전까지는. 하이잘 산에서 군단이 패퇴한 뒤, 스랄은 불모의 땅 동부를 차지하고 서슬갈기 가시멧돼지를 몰아낸 다음 그 땅을 듀로타라 이름 짓고 오그리마를 수도로 세웠다.\n\n이 땅에는 더 오래된 슬픔도 서려 있다. 데소린이라는 사내가 사랑하는 알루라나가 다른 이의 품에 안긴 것을 보았고, 그의 절규가 모래 속에서 도끼 킬메임을 뽑아 올렸다고 한다. 그가 그녀를 죽이는 데 쓴 바로 그 도끼였다.",
		source = "https://warcraft.wiki.gg/wiki/Barrens_(Classic)",
	},
	[1414] = {
		name = "칼림도어",
		short = "대분리가 세계를 부순 뒤, 남은 나이트 엘프들은 의도적으로 세상과 발길을 끊었다.",
		full = "대분리가 세계를 부순 뒤, 남은 나이트 엘프들은 의도적으로 세상과 발길을 끊었다. 인간들 사이에서 칼림도어는 전설로만 남았다. 부서져 파도 아래로 가라앉았다는 땅, 위치도 모습도 알 수 없는 땅이었다.\n\n하지만 완전히 잊힌 것은 아니었다. 그 후로도 나이트 엘프들은 쿠엘도레이를 찾아왔고, 그 덕분에 쿠엘탈라스의 하이 엘프들만은 그 전설이 사실임을 알고 있었다.\n\n3차 대전쟁이 닥쳤을 때에도 인간 대부분은 칼림도어의 존재를 믿지 않았고, 테레나스 왕의 궁정에 파견된 키린 토의 대사조차 의심하는 이들 가운데 있었다. 메디브의 경고에 귀를 기울여 서쪽으로 배를 띄운 이는 소수뿐이었는데, 스랄의 새로운 호드가 그중 하나였고 제이나 프라우드무어의 원정대가 그 뒤를 따랐다. 그들이 발견한 것은 전설이 아니라 온전한 하나의 대륙이었다. 북쪽에는 얼음이, 남쪽에는 사막이 펼쳐져 있었고, 그 사이의 숲은 여전히 나이트 엘프들이 지키고 있었다.",
		source = "https://warcraft.wiki.gg/wiki/Kalimdor",
	},
	[1415] = {
		name = "동부 왕국",
		short = "동부 왕국이 처음부터 여러 땅으로 나뉘어 있던 것은 아니다.",
		full = "동부 왕국이 처음부터 여러 땅으로 나뉘어 있던 것은 아니다. 한때 이곳은 하나의 대륙이었으나, 대분리가 세계를 찢어 놓으면서 지금은 아제로스, 카즈 모단, 로데론이라 불리는 부서진 조각들만 남았다. 쿠엘탈라스는 그 마지막 조각난 땅의 북쪽에 매달려 있는데, 지금도 그곳이 독립된 땅인지 아니면 다른 땅의 한 귀퉁이일 뿐인지 분명하지 않다.\n\n이 조각들을 가로질러 카즈 모단의 산맥과 붉은마루 산맥이 대륙의 심장부를 관통하는 등뼈처럼 솟아 있고, 그 주위로 오래된 종족들이 살아가고 있다. 깊은 전당의 드워프와 노움, 여러 왕국의 인간, 숲의 하이 엘프, 그리고 이제는 로데론의 백성이 살던 곳에서 되살아난 포세이큰까지. 오크, 고블린, 나가, 오우거도 이 땅에 발을 들였지만, 이 땅에서 태어난 종족은 아니다.\n\n그 첫 번째 붕괴의 상처는 여전히 이곳의 진실로 남아 있다. 이곳의 모든 국경, 한 왕국과 다음 왕국 사이의 모든 해협과 물에 잠긴 땅은 동부 왕국이 한때 하나였고 이제는 더 이상 하나가 아님을 기억하고 있다.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Kingdoms",
	},
	[1416] = {
		name = "알터랙 산맥",
		short = "이 봉우리들에는 비가 좀처럼 그치지 않고, 그 위의 하늘은 언제나 잿빛이다. 한때 이 산맥은 북부 대부분을 다스리던 도시국가 알터랙의 왕관이었고, 달라란도 품고 있었다.",
		full = "이 봉우리들에는 비가 좀처럼 그치지 않고, 그 위의 하늘은 언제나 잿빛이다. 한때 이 산맥은 북부 대부분을 다스리던 도시국가 알터랙의 왕관이었고, 달라란도 품고 있었다. 이제 둘 다 사라졌으며, 남은 것을 보면 왜 이곳을 오르려는 이가 그토록 적은지 알 수 있다.\n\n2차 대전쟁이 끝났을 때, 로데론 연합은 알터랙의 영주들이 호드와 몰래 내통했다는 사실을 알고 배신자들을 그들의 본거지에서 치기 위해 이 산맥으로 군대를 보냈다. 도시는 함락되었고 백성은 흩어지거나 투옥되었으며, 그 혈통은 끝내 왕좌를 되찾지 못했다. 몰락한 가문의 후대 왕자인 알리덴 페레놀드는 도적 두목으로 일어나 추방자와 복수심에 불타는 자들을 비밀결사로 불러 모았다. 이 무법자 집단은 지금도 스트란브래드를 장악하고 이 비탈 곳곳을 누비며 그의 가문이 잃은 것을 되찾으려 한다.\n\n오늘날 알터랙 성의 폐허는 산사태 오우거의 차지가 되었고, 오우거가 차지하지 못한 곳의 대부분은 비밀결사가 쥐고 있다.",
		source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
	},
	[1417] = {
		name = "아라시 고원",
		short = "소라딘 왕은 이곳에서 그의 백성이 번영하리라는 꿈을 꾸고 이 메마른 땅에 왔으며, 통일된 아라소르의 첫 수도인 스트롬을 세웠다.",
		full = "소라딘 왕은 이곳에서 그의 백성이 번영하리라는 꿈을 꾸고 이 메마른 땅에 왔으며, 통일된 아라소르의 첫 수도인 스트롬을 세웠다. 메마른 땅은 그에게 가시 울타리 역할을 해 주어 아마니의 숲 트롤이 매복할 곳을 주지 않았고, 그는 거기에 더해 두 번째 성벽까지 쌓았다. 천 년 동안 스트롬은 제국의 심장부에 서 있었으나, 귀족 가문들은 더 비옥한 땅을 찾아 하나둘 떠나갔고 소라딘의 마지막 후손들도 스톰윈드를 세우러 떠났다. 남은 곳은 스트롬가드가 되었고, 그 뒤로 줄곧 트롤베인 가문이 다스렸다.\n\n그 후 스트롬가드는 오우거와 비밀결사에게 짓밟혀 함락되었고, 생존자들은 요새에서 쫓겨나 지금은 임시 주둔지라 부르는 협곡으로 물러났다. 가까이에는 해머폴이 있다. 한때 인간이 오크 포로를 가두던 수용소였으나, 지금은 오크들이 직접 차지하고 오그림 둠해머의 이름을 따 새로 이름을 붙였다.\n\n소라딘의 거대한 성벽은 무너져 휑한 폐허가 되었고, 그의 요새는 부서진 채 여전히 분쟁의 땅으로 남아 있다. 오우거와 비밀결사, 그리고 그곳을 되찾으려는 왕국의 마지막 병사들이 지금도 그곳을 두고 싸운다.",
		source = "https://warcraft.wiki.gg/wiki/Arathi_Highlands_(Classic)",
	},
	[1418] = {
		name = "황야의 땅",
		short = "황야의 땅은 메마른 흙과 흩어진 바위, 굽이진 협곡으로 이루어진 갈라진 사막이며, 사방이 산으로 막혀 있다. 코요테와 퓨마, 대머리수리 말고는 이곳에서 살아남는 것이 거의 없다.",
		full = "황야의 땅은 메마른 흙과 흩어진 바위, 굽이진 협곡으로 이루어진 갈라진 사막이며, 사방이 산으로 막혀 있다. 코요테와 퓨마, 대머리수리 말고는 이곳에서 살아남는 것이 거의 없다.\n\n북쪽 끝에는 고대 대지인이 만든 울다만의 폐허가 있다. 울다만이 발굴되었을 때 그곳은 드워프의 고귀한 기원에 대한 첫 단서를 내놓았고, 아이언포지의 탐사꾼들이 티탄의 유물을 찾아 폐허로 몰려들었다. 그러나 수천 년의 잠에서 깨어난 돌무덤 트로그가 탐험가들을 학살했고, 지금은 빼앗은 도시를 사납게 지키고 있다. 울다만 바로 남쪽에는 거대한 검은무쇠 요새가 서 있는데, 그곳의 드워프들은 먼지목도리 부족 오우거, 그리고 동쪽의 검은용 무리 사이에 둥지를 튼 비룡들과 전쟁을 벌이고 있다.\n\n훗날 이곳에는 카즈 모단에서 유일한 호드 전초기지인 카르가스가 세워졌다. 변절한 검은바위 동족을 감시하기 위해 오크들이 세운 곳이다. 대족장 스랄은 직접 카르가스 원정대를 보내 렌드 블랙핸드를 추적하게 했다.",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
	},
	[1419] = {
		name = "저주받은 땅",
		short = "저주받은 땅이라는 이름은 과장이 아니다. 발밑의 붉은 진흙은 한때 검은늪이라 불리던 어두운 늪지의 황갈색 흙이었다. 오크 호드가 이곳에서 어둠의 문을 찢어 열고 아제로스로 쏟아져 들어오기 전까지는.",
		full = "저주받은 땅이라는 이름은 과장이 아니다. 발밑의 붉은 진흙은 한때 검은늪이라 불리던 어두운 늪지의 황갈색 흙이었다. 오크 호드가 이곳에서 어둠의 문을 찢어 열고 아제로스로 쏟아져 들어오기 전까지는. 그날 새어 나온 마법이 흙을 붉게 태우고 영영 죽여 버렸다. 이제 이곳에는 억센 사막 덤불과, 그만큼 억센 사막의 생물들, 곧 바실리스크와 전갈과 하이에나 말고는 아무것도 자라지 않는다.\n\n대마법사 카드가와 키린 토는 무너진 관문을 감시하고 다시는 아무것도 그곳을 통과하지 못하도록 네더가드 요새를 세웠다. 평화는 두 해 동안 이어졌으나, 드레노어의 호드가 어둠의 문을 다시 열고 요새를 포위했다. 넬쥴의 의식이 드레노어를 찢어발기기 시작하자, 카드가와 마법사들은 굴단의 해골을 사용해 저편에서 어둠의 문의 돌 틀을 산산조각 냈고, 두 세계를 잇는 다리를 영원히 끊어 버렸다.\n\n오늘날에도 네더가드의 마법사와 성기사들은 죽은 어둠의 문을 음울하게 지키고 있다. 그들은 누구도 믿지 않고 어떤 실수도 용납하지 않는, 엄격하고 무뚝뚝한 공동체이다. 동쪽 바다에서 몰려온 폭풍우조차 구워진 땅 위를 쓸고 흘러가 버려 아무 도움이 되지 않는 이 땅에서, 그곳은 유일한 피난처이다.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
	},
	[1420] = {
		name = "티리스팔 숲",
		short = "티리스팔 숲의 하늘은 수년째 병든 초록빛으로 드리워 있고, 나무들은 역병이 남겨 준 생명에 간신히 매달려 있다.",
		full = "티리스팔 숲의 하늘은 수년째 병든 초록빛으로 드리워 있고, 나무들은 역병이 남겨 준 생명에 간신히 매달려 있다. 한때 이곳은 테레나스 왕의 치세 아래 평화로운 농장들이었고, 여러 세대가 방앗간과 호박밭 사이에서 조용히 살았다. 그 삶은 아서스 메네실이 로데론을 유린하고 시골 전역에 역병을 퍼뜨려 백성을 죽이고 리치 왕의 노예로 되살리면서 끝났다. 죽은 이가 너무 많아 제대로 묻어 주지 못한 곳에는 지금도 거대한 공동묘지가 남아 있다. 몇 달 뒤 발니르 농장 근처에서 실바나스 윈드러너는 밴시들을 이끌고 아서스에게 반기를 들어 그 죽음의 기사에게 독화살을 박아 넣었으나, 켈투자드의 해골 병사들에게 밀려났다.\n\n그 폐허에서 실바나스의 자유 의지를 지닌 망자들, 곧 포세이큰이 태어나 이 땅을 자신들의 것으로 삼았다. 그들의 적은 결코 이 땅을 떠나지 않았다. 북쪽의 옛 붉은십자군 수도원은 인간이 아닌 모든 것을 불태우고 사냥하는 광신자, 붉은십자군이 장악하고 있다.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "은빛소나무 숲",
		short = "은빛소나무 숲, 간단히 은빛소나무라고도 불리는 이곳은 로데론의 험준한 서부 해안을 따라 펼쳐진 광활하고 오래된 숲이다. 땅은 제법 평평한 곳부터 구릉진 곳까지 다양하며, 더 높은 산들 사이에 포근히 자리하고 있다.",
		full = "은빛소나무 숲, 간단히 은빛소나무라고도 불리는 이곳은 로데론의 험준한 서부 해안을 따라 펼쳐진 광활하고 오래된 숲이다. 땅은 제법 평평한 곳부터 구릉진 곳까지 다양하며, 더 높은 산들 사이에 포근히 자리하고 있다. 숲은 섬뜩할 만큼 고요하며, 이따금 나무 사이로 울려 퍼지는 기이한 울부짖음만이 그 정적을 깬다. 이끼 낀 바위 턱이 차가운 바람에 떨고, 나무들은 모두 병들었거나 죽어 가고 있다. 허물어진 농가와 버려진 광산이 곳곳에 흩어져 있으며, 이제는 숲의 더 어두운 존재들이 그곳에 깃들어 산다.\n\n이 숲은 유령이 출몰하는 거친 곳으로, 은빛 껍질의 키 큰 소나무들이 풀이 덮인 둔덕 위로 우뚝 솟아 있는 것이 특징이다. 이곳이 푸르고 생기 넘치던 시절에는 얼라이언스가 은빛소나무 숲을 지켰다. 이제 이곳은 유령 같은 안개에 휩싸여 있다. 포세이큰이 숲 북부를 장악하고 비열한 썩은가죽 놀과 끊임없이 충돌한다. 남은 인간들은 숲 남부를 지키고 있지만, 절박한 처지에 병력도 얇게 흩어져 있다. 달라란은 이 사람들을 지키고 언데드 역병과 늑대인간의 저주를 연구하기 위해 은빛소나무 숲으로 자주 원정대를 보낸다. 늑대인간의 저주란 달이 뜨면 희생자를 피에 굶주린 늑대인간 괴물로 변하게 하는 수수께끼의 병이다.\n\n숲의 남쪽은 길니아스와 힐스브래드 구릉지에 닿아 있고, 북쪽에는 티리스팔 숲이 있다. 로다미어 호수는 은빛소나무 숲의 동쪽 경계를 이룬다.\n\n이 땅은 포세이큰의 영토이지만, 달라란의 마법사들과, 폐허가 된 들판과 농가 일부를 차지한 스컬지의 하수인들이 그 소유권을 다투고 있다. 썩은가죽 놀은 수수께끼의 펜리스 섬을 거점으로 삼아, 감히 그들의 일에 다가오는 자는 누구든 사납게 공격한다. 남서쪽에는 장작나무 마을이 있는데, 그곳 주민들은 대마법사 아루갈의 저주에 걸려 밤이면 피에 굶주린 늑대인간으로 변한다. 아루갈은 근처 그림자송곳니 성채의 어두운 탑에 머물고 있다.\n\n은빛소나무 숲에서는 전투가 잦다. 사우스쇼어의 얼라이언스 병력이 이 버려진 숲으로 와서 공동묘지를 공격하거나 그림자송곳니 성채로 들어가기 때문이다. 이곳은 포세이큰 본토의 끝자락이자, 언데드 역병의 영향이 초목에서 드러나는 가장 남쪽 지점이다.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "서부 역병지대",
		short = "한때 이곳은 로데론 북부에서 가장 아름다운 농토였다. 숲이 우거지고 푸르렀으며, 안돌할에서 왕국의 곡창을 채웠고 하스글렌의 영주관에서 다스려졌다.",
		full = "한때 이곳은 로데론 북부에서 가장 아름다운 농토였다. 숲이 우거지고 푸르렀으며, 안돌할에서 왕국의 곡창을 채웠고 하스글렌의 영주관에서 다스려졌다. 바로 그 풍요가 이 땅을 파멸시킨 무기가 되었다.\n\n리치 왕의 계획에 따라 저주받은 교단은 그의 역병 기운을 휴대용 가마솥에 담아 남쪽으로 옮겼고, 충성스러운 교단 신도들의 마을에 숨겨 두었으며, 가장 큰 네 개는 안돌할의 들판에 직접 설치했다. 곡물 자체가 오염되었고, 그 곡물은 아무도 의심하지 않은 짐마차에 실려 로데론 전역으로 퍼져 나갔다. 자기 손으로 구운 빵을 먹은 사람들은 병들어 죽었고, 리치 왕의 노예로 되살아났다. 숲은 끝내 회복되지 못했다. 소나무들은 병든 안개 아래 잿빛으로 서서 갈색 바늘잎을 매달고 있으며, 줄기는 종양 같은 혹으로 부풀어 있다.\n\n남아 있는 질서는 왕국이 무너진 뒤 간신히 건져 낸 것이다. 붉은십자군은 하스글렌의 마르덴홀드 요새를 점령하고, 그곳에서 나머지 땅을 장악한 언데드를 향해 출격했다. 그 모든 혼란 속에서 평화를 지키는 곳은 단 하나, 빛의 인도자 우서에게 봉헌된 우서 경의 무덤뿐이다. 역병이 한 번도 닿지 않은 땅이다.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "동부 역병지대",
		short = "이곳의 땅은 한때 농토였고, 로데론의 제2의 도시 스트라솔름 주변으로 동쪽 숲의 마을들이 흩어져 있었다. 그중 남은 것은 하나도 없다.",
		full = "이곳의 땅은 한때 농토였고, 로데론의 제2의 도시 스트라솔름 주변으로 동쪽 숲의 마을들이 흩어져 있었다. 그중 남은 것은 하나도 없다. 이제 흙은 갈색으로 병들었고, 나무들은 버섯처럼 부풀었으며, 공기는 주황빛 안개로 자욱하다.\n\n아서스 왕자가 이미 마을 사람들을 앗아 간 역병의 근원을 쫓아 온 곳이 바로 스트라솔름이었다. 백은의 손의 수장 우서 경은 그가 도시를 정화하는 것을 거부했다. 아서스는 그의 지휘권을 박탈하고 그 자리에서 백은의 손을 해산한 뒤, 스트라솔름 주민들이 스컬지로 되살아나게 두느니 자기 손으로 그들을 칼로 베었다. 그는 거기서 멈추지 않았다. 공포의 군주 말가니스를 쫓아 북쪽으로 갔다가 죽음의 기사가 되어 돌아왔고, 자신의 아버지를 죽여 로데론 왕국을 끝장냈다.\n\n알렉산드로스 모그레인은 백은의 손의 잔존 세력으로 십자군을 일으켜 폐허를 되찾고자 했다. 그는 티르의 손 수도원과 스트라솔름의 절반을 점령했지만, 그가 죽자 그의 기사단은 은빛 여명회와 붉은십자군으로 갈라졌다. 붉은십자군은 지금도 이 들판을 장악한 채 스컬지와 끝없는 전쟁을 벌이고 있으며, 다른 누구도 반기지 않는다.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "힐스브래드 구릉지",
		short = "힐스브래드의 흙은 비옥하고 언덕은 푸르다. 여행자들은 역병이 오기 전 로데론 전체가 이런 모습이었다고 말한다.",
		full = "힐스브래드의 흙은 비옥하고 언덕은 푸르다. 여행자들은 역병이 오기 전 로데론 전체가 이런 모습이었다고 말한다. 그것은 이 땅의 위안인 동시에 잔인함이기도 하다. 이 땅은 다른 모든 곳에서 잃어버린 것을 기억하고 있지만, 이곳을 지키는 사람들은 나머지 땅을 파멸시킨 바로 그 전쟁을 여전히 치르고 있기 때문이다.\n\n2차 대전쟁 초기, 오크 약탈자들이 해안 마을들을 습격했고, 오그림 둠해머는 줄진을 감옥에서 풀어 주기 위해 직접 던홀드 요새로 진격했다. 수십 년 뒤 이 언덕을 지나간 이는 스랄이었다. 그는 흩어진 오크 부족들을 규합한 뒤 밤에 사우스쇼어로 숨어들어 배를 훔쳤고, 새로운 호드를 태우고 바다 건너 칼림도어로 떠났다.\n\n오크들이 시작한 일을 포세이큰이 이어 가고 있다. 그들은 타렌 밀농장을 가장 남쪽의 거점으로 삼아, 얼라이언스를 위해 굳건히 버티는 사우스쇼어와 힐스브래드 농장의 인간들을 공격하는 전진 기지로 만들었다.\n\n이제 농토 곳곳에는 소나무 숲이 흩어져 있고, 길은 여전히 목초지를 가로질러 북쪽의 음울한 포세이큰 정착지로 이어진다. 마치 이 땅 자체가 어느 편이 자신을 차지할지 아직도 기다리고 있는 듯하다.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "동부 내륙지",
		short = "세 망치의 전쟁이 끝난 뒤, 와일드해머 드워프는 그림 바톨의 굴을 버리고 북쪽으로 와서 맹금의 봉우리에 땅 위의 보금자리를 지었다.",
		full = "세 망치의 전쟁이 끝난 뒤, 와일드해머 드워프는 그림 바톨의 굴을 버리고 북쪽으로 와서 맹금의 봉우리에 땅 위의 보금자리를 지었다. 그들은 돌과 대장간을 등지고 하늘과 날개를 향했으며, 이 지역의 야생 그리핀과 워낙 깊은 유대를 맺어 그 인연을 기리고자 도시 안에 거대한 그리핀 석상을 세우기까지 했다. 이미 이 땅을 차지하고 있던 숲 트롤, 한때 위대했던 아마니 제국의 잔당은 드워프를 조상의 땅에 무단으로 눌러앉은 자들로 여기고 틈만 나면 그리핀 둥지를 습격했다.\n\n2차 대전쟁 때 호드가 휩쓸고 지나가자, 그때까지 그런 침략자가 존재하는지조차 몰랐던 영주 쿠르드란 와일드해머와 그의 기수들은 폭풍의 기운이 서린 망치를 들고 하늘에서 오크 행렬을 덮쳐 쉴 새 없이 몰아붙였다. 오그림 둠해머는 얼라이언스의 병력을 동부 내륙지로 끌어들여 쿠엘탈라스를 아무 저항 없이 치고자 했지만, 안두인 로서는 그 계획을 꿰뚫어 보고 직접 쿠르드란의 곁으로 달려갔다. 두 사람은 함께 침략자들을 무찌르고 알터랙 산맥까지 몰아냈다. 그 일로 쿠르드란은 자기 백성이 얼라이언스를 돕겠다고 맹세했다.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "던 모로",
		short = "던 모로에는 눈이 깊게 쌓여 있으며, 사방이 카즈 모단의 산맥으로 둘러싸여 있고, 그 고갯길은 언제나 드워프 병사들이 지키고 있다.",
		full = "던 모로에는 눈이 깊게 쌓여 있으며, 사방이 카즈 모단의 산맥으로 둘러싸여 있고, 그 고갯길은 언제나 드워프 병사들이 지키고 있다. 이 산맥이 다른 누구의 것이 되기 전에는 서리갈기 얼음 트롤의 땅이었다. 그들은 먼 옛날 드라카리 제국에서 떨어져 나와 이 지역에 정착했다.\n\n그 사정은 최초의 노움들이 울다만에서 기어 나와 추위와 트롤 모두에게서 살아남는 데 지혜를 쏟으며 봉우리 깊숙이 요새화된 거처를 파면서 달라졌다. 오백 년 뒤 드워프들도 지평선 너머로 보았던 같은 산맥에 이끌려 울다만에서 올라왔고, 가장 높은 봉우리 아래에 아이언포지를 세웠다. 노움들이 이미 근처에 자리 잡고 있는 것을 본 두 종족은 한 번도 깨진 적 없는 우정을 맺었다. 드워프는 힘을 보태 놈리건을 세웠고, 노움은 기계의 비밀을 나누었다. 두 종족의 군대는 함께 서리갈기 트롤을 무찌르고 살아남은 자들을 언덕으로 몰아내어, 이 땅에 대한 트롤의 지배를 영원히 끝냈다.\n\n이제 놈리건은 사라져 폐허가 되었고, 그 백성은 피난처를 찾아 아이언포지로 몰려들었다.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "이글거리는 협곡",
		short = "한때 이곳은 붉은마루 산맥의 일부인 푸른 땅이었다. 이백삼십여 년 전, 대지 자체가 찢겨 나가기 전까지는.",
		full = "한때 이곳은 붉은마루 산맥의 일부인 푸른 땅이었다. 이백삼십여 년 전, 대지 자체가 찢겨 나가기 전까지는.\n\n세 망치의 전쟁 때 검은무쇠 드워프의 마법사 영주 타우릿산은 적을 무너뜨릴 무기를 찾았다. 그는 가장 신임하는 일곱 드워프와 함께 세계의 밑바닥으로 손을 뻗어, 잠들어 있어야 했던 힘을 불러냈다. 응답한 것은 하인이 아니라 주인이었다. 바로 고대의 불의 군주 라그나로스였다. 그가 깨어나면서 검은바위 산이 땅에서 솟구쳤고, 수십 리에 걸친 땅이 검게 그을렸으며, 검은무쇠 드워프의 수도 타우릿산은 그 아래에서 잔해로 짓뭉개졌다. 남쪽의 그을린 평원은 불타는 평원으로, 북쪽의 이 황폐한 골짜기는 이글거리는 협곡으로 알려지게 되었다.\n\n그 파멸 이후 모든 검은무쇠 드워프가 부족에 충성을 지킨 것은 아니었다. 그중 일부는 떨어져 나와 스스로를 토륨 형제단이라 칭했고, 옛 동족이 골짜기 바닥에 파 들어간 거대한 발굴지를 내려다보는 곳에 토륨 조합 거점을 세워 위에서 검은무쇠 드워프의 작업을 지켜보고 있다.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "불타는 평원",
		short = "불타는 평원의 하늘은 검은바위 산의 간헐적인 분화로 밝혀져 한 번도 붉은빛을 잃은 적이 없고, 땅은 결코 식지 않는다.",
		full = "불타는 평원의 하늘은 검은바위 산의 간헐적인 분화로 밝혀져 한 번도 붉은빛을 잃은 적이 없고, 땅은 결코 식지 않는다. 어둠의 문이 열리기 이백 년 전, 검은무쇠 드워프는 아이언포지에서 추방당해 이곳으로 왔다. 그들의 마법사 영주 타우릿산은 정령 하수인을 소환해 브론즈비어드와 와일드해머 부족을 상대로 세 망치의 전쟁에서 승리하려 했다. 응답한 것은 하수인이 아니라, 한때 티탄에게 추방당했던 불의 군주 라그나로스였다. 그의 강림은 주변 산들을 녹이고 폭발의 중심에 화산을 솟게 했으며, 그를 소환한 드워프들을 파멸시켰다. 그 새 봉우리 북쪽은 이글거리는 협곡이 되었고, 남쪽은 불타는 평원이 되어 그 이후로 줄곧 상처를 안고 있다.\n\n1차 대전쟁 때 오크들은 화산의 비탈에 정착했고, 2차 대전쟁 내내 검은바위 첨탑을 요새로 삼았다. 이후 검은바위 오크들이 돌아와 지금도 그곳에 머물며, 스랄의 휴전 이전의 잔혹한 옛 방식을 따르고 있다. 네파리안이 이끄는 검은용들이 첨탑의 위층을 차지하고 있으며, 라그나로스는 여전히 그 모든 것 아래 어딘가에서 분노를 곱씹고 있다고 한다.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "엘윈 숲",
		short = "1차 대전쟁 때 오크들이 쳐들어오자 수천의 병력이 엘윈 숲을 지나 스톰윈드를 에워쌌고, 바다를 제외한 모든 곳과 도시를 단절시켰다.",
		full = "1차 대전쟁 때 오크들이 쳐들어오자 수천의 병력이 엘윈 숲을 지나 스톰윈드를 에워쌌고, 바다를 제외한 모든 곳과 도시를 단절시켰다. 기사 대장 안두인 로서는 스톰윈드 기사단을 이끌고 숲을 가로질러 돌격해, 오크의 후방 부대를 기습하여 흩어 놓았다. 그 덕분에 도시는 시간을 벌었지만 충분하지는 않았다. 대족장 블랙핸드는 곧 호드와 왕 사이에 남은 마지막 마을인 골드샤이어와 문브룩을 점령했고, 스톰윈드 성은 약탈당했다. 로서는 생존자들을 이끌고 바다를 건너 로데론으로 떠났고, 도시의 폐허는 한동안 폭풍불꽃 부족의 차지가 되었다. 지금도 이 지역 곳곳에는 부서져 썩어 가는 오크 투석기가 흩어져 있다. 그 점령의 흔적으로 남은 것은 그것뿐이다.\n\n도시 동쪽의 노스샤이어 포도밭은 한때 스톰윈드 농부들의 자랑이었다. 석공 조합은 폐허가 된 수도를 재건하는 데 여러 해를 바쳤지만 대가를 받지 못했고, 귀족들은 빚을 갚는 대신 조합을 해산해 버렸다. 조합장 에드윈 밴클리프의 분노는 폭동으로 번져 티핀 엘러리안 린 왕비의 목숨을 앗아 갔고, 데피아스 단을 낳았다. 데피아스 단은 노스샤이어에서 농부들을 몰아내고 그 들판을 점령했다.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "죽음의 고개",
		short = "죽음의 고개는 아제로스 중부의 산맥을 가로지르며 그늘숲과 슬픔의 늪을 잇는다. 이십여 년 전만 해도 이곳은 붉은마루 산맥의 일부로 여겨졌다.",
		full = "죽음의 고개는 아제로스 중부의 산맥을 가로지르며 그늘숲과 슬픔의 늪을 잇는다. 이십여 년 전만 해도 이곳은 붉은마루 산맥의 일부로 여겨졌다.\n\n한때 어둠의 마법사 메디브의 권좌였던 카라잔의 상아탑이 이 험준한 지역의 한가운데에 서서 사악한 마법을 땅으로 흘려보내고 있다. 나무들은 잎 하나 없이 돌처럼 굳었고, 협곡 사이로 끔찍한 바람이 울부짖는다. 오우거와 악마, 언데드, 그리고 소수의 인간 유랑민이 이곳 안쪽을 떠돈다. 그리고 어떤 새로운 세력이 상아탑을 차지했으며 오우거와 악마들이 그 지배 아래 있다는 소문이 은밀히 돈다.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "그늘숲",
		short = "그늘숲에는 부자연스러운 밤이 장막처럼 드리워 있으며, 그것은 한 번도 걷힌 적이 없다.",
		full = "그늘숲에는 부자연스러운 밤이 장막처럼 드리워 있으며, 그것은 한 번도 걷힌 적이 없다. 한때 엘윈 숲의 아름다운 한 자락이었던 이곳은 이제 저주받아 죽어 가는 땅이다. 검은 안개 아래에서 나무들은 뒤틀려 자랐고, 죽은 자들은 무덤에서 일어났으며, 엘룬의 낫이 일으킨 힘에 이끌린 늑대인간들이 어둠과 함께 슬금슬금 스며들었다. 죽음의 고개에서 밀려드는 오우거들은 그 비참함을 더욱 깊게 할 뿐이었다.\n\n스톰윈드의 보호는 오래전에 이곳에서 아무 의미가 없어졌고, 남은 사람들은 그 보호 없이 땅을 지키는 법을 익혔다. 그들의 민병대인 밤의 감시단은 길을 순찰하며, 그림자 속에서 움직이는 모든 것으로부터 다크샤이어를 지킨다. 해골 전사와 구울, 사나운 늑대인간, 그리고 데피아스 단원들까지.\n\n숲의 심장부에는 오래전에 죽은 화산의 분화구가 있으며, 그곳은 주변의 어둠보다 한결 부드러운 황혼에 감싸여 있다. 그 안에는 에메랄드의 꿈을 향해 뿌리를 뻗은 거대한 나무 가운데 하나가 서 있고, 잠든 드루이드들의 영향이 근처에서 자라는 모든 것에 물들어 있다. 그 너머로는 버려진 농가들과, 어둠이 내린 뒤로 해마다 채워져 온 까마귀 언덕 묘지의 넓은 무덤들이 펼쳐져 있다.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "모단 호수",
		short = "모단 호수의 물은 잿빛 바위에 포근히 안겨 돌다지 댐에 가두어져 있다. 아제로스의 그 어떤 건축물도 따라온 적이 없는 드워프 공학의 걸작이다.",
		full = "모단 호수의 물은 잿빛 바위에 포근히 안겨 돌다지 댐에 가두어져 있다. 아제로스의 그 어떤 건축물도 따라온 적이 없는 드워프 공학의 걸작이다. 사방으로 산이 깎아지른 듯 솟아 있고 소나무와 자작나무가 드문드문 자라며, 호수는 마치 한 번도 흔들린 적 없는 것처럼 고요하고 잔잔하다.\n\n이 호수는 한때 전쟁터였다. 2차 대전쟁 때 호드의 오크들이 이 지역으로 몰려들어 이곳에서 얼라이언스에 맞서 최후의 저항을 벌였다. 아이언포지는 버텨 냈다. 그 드워프들은 오크를 몰아내고 모단 호수를 되찾았지만, 그 전쟁의 잔해는 끝내 다 치워지지 않았다. 부서진 투석기와 산산조각 난 대형 쇠뇌가 지금도 호수 바닥과 섬들 곳곳에 반쯤 가라앉은 채 흩어져 있다. 이 고요한 물이 한때 살육의 현장이었다는 증거로 남은 것은 그것뿐이다.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "붉은마루 산맥",
		short = "붉은마루 산맥은 엘윈 숲의 동쪽, 그늘숲의 북동쪽, 불타는 평원의 남쪽에 자리하고 있다.",
		full = "붉은마루 산맥은 엘윈 숲의 동쪽, 그늘숲의 북동쪽, 불타는 평원의 남쪽에 자리하고 있다.\n\n세차게 흐르는 강과 우뚝 솟은 느릅나무, 점점 높아지는 지형이 어우러진 목가적인 이 지역은 스톰윈드의 보호를 받고 있지만, 2차 대전쟁 이후로는 명목상 독립된 땅이다. 이곳은 여전히 아제로스에 몇 남지 않은 평화로운 지역 가운데 하나로, 주민들은 평온하고 만족스럽게 살며 스톰윈드에 목재와 생선, 곡물을 공급한다. 그러나 평화가 완전하지는 않다. 불타는 평원에서 온 검은바위 오크 무리가 돌망루 요새를 차지하고 있는데, 지금까지는 자기들끼리만 지내고 있다. 서부 몰락지대의 참상에 비하면 붉은마루는 아직 버티고 있는 셈이다.\n\n영원의 호수 북쪽 기슭에는 레이크샤이어 마을이 있는데, 주변 언덕에서 내려온 놀과 검은바위 오크에게 포위당해 있다. 그 남쪽에는 붉은마루 삼거리라 불리는 갈림길이 있어 레이크샤이어를 엘윈과 그늘숲으로 잇고, 호수마루 오솔길을 통해 돌망루 요새로도 이어진다. 그 길에는 새끼용과 놀, 멀록, 야수들이 도사리고 있다.\n\n호수의 수면은 충분히 잔잔해 보이지만 그 아래에는 멀록이 숨어 있고, 깊은 곳에 바다 괴물이 산다는 소문도 끊이지 않는다.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "가시덤불 골짜기",
		short = "가시덤불 골짜기는 그늘숲 남쪽에 펼쳐진 광활한 밀림이다. 정글 트롤이 이 찌는 듯한 열대 우림을 순찰하고 나가가 해안을 따라 사냥하며, 목을 조르는 가시덤불 덩굴과 야수들 탓에 여행은 위험하기 그지없다.",
		full = "가시덤불 골짜기는 그늘숲 남쪽에 펼쳐진 광활한 밀림이다. 정글 트롤이 이 찌는 듯한 열대 우림을 순찰하고 나가가 해안을 따라 사냥하며, 목을 조르는 가시덤불 덩굴과 야수들 탓에 여행은 위험하기 그지없다.\n\n이 골짜기는 한때 구루바시 제국의 심장부였고, 그 거대한 도시들이 지역 곳곳에 서 있었다. 제국이 무너진 뒤 그 도시들은 폐허로 허물어졌지만, 트롤들은 지금도 그 사이에서 살고 있다. 북동쪽의 줄구룹은 한때 구루바시의 수도였다.\n\n무법항은 원래 인간들이 세운 작은 항구 마을이었으나 트롤들에게 짓밟혔다. 이후 스팀휘들 무역회사의 고블린들이 만에서 트롤을 몰아내고 그곳을 차지했으며, 동부 왕국에서의 활동 중심지로 키워 냈다.\n\n북쪽에는 쿠르젠 대령의 원정대가 세운 주둔지가 있다. 그곳에서 대령의 정신은 오우거 마법사 마이조스에게 사로잡혔다. 마이조스는 정신의 눈이라는 유물로 쿠르젠의 의지를 꺾어 그의 부하들을 지휘했다. 쿠르젠의 병사 일부는 사로잡힌 지휘관에게 반기를 들고 서쪽으로 달아나, 그에게 맞서 반란군 야영지를 세웠다.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "슬픔의 늪",
		short = "늪의 검은 물 아래에는 이곳에 슬픔이라는 이름을 붙인 그 슬픔보다도 오래된 신전이 잠겨 있다.",
		full = "늪의 검은 물 아래에는 이곳에 슬픔이라는 이름을 붙인 그 슬픔보다도 오래된 신전이 잠겨 있다. 구루바시 제국이 무너지자 아탈라이라 불리는 변절한 트롤 무리가 늪지대로 달아나 아탈학카르 신전을 세웠고, 그곳에서 그들의 어둠의 로아인 영혼의 약탈자 학카르를 세상으로 다시 불러내기 위해 끔찍한 의식을 행했다. 그들의 마법은 신전 주변의 식물과 짐승을 뒤틀었고, 결국 그 타락은 눈에 띄지 않을 수 없게 되었다. 꿈의 여왕 이세라는 교단의 야망을 알아채고 자신의 힘으로 그들에 맞섰으며, 학카르가 돌아오기 전에 신전을 가장 큰 늪 아래로 가라앉혔다. 그러나 그녀는 트롤들이 자신들의 신을 영원히 포기하리라 믿지 않았다. 그녀는 배우자 에라니쿠스와 녹색용 무리를 보내 폐허를 영원히 감시하게 하여, 다시는 그곳이 그러한 악을 세상에 풀어놓는 데 쓰이지 않도록 했다. 녹색용족은 지금도 그녀의 명령에 따라 이 늪지를 순찰하며, 가라앉은 사원은 파괴되지 않은 채 감시를 받으며 물 아래 봉인되어 있다.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "서부 몰락지대",
		short = "이제 서부 몰락지대의 들판 위로는 바람이 막힘없이 불어 간다. 그것을 막아 줄 높은 것이 하나도 남아 있지 않기 때문이다. 한때 이곳은 스톰윈드의 곡창 지대로서 여러 세대에 걸쳐 젊은 왕국을 먹여 살렸다.",
		full = "이제 서부 몰락지대의 들판 위로는 바람이 막힘없이 불어 간다. 그것을 막아 줄 높은 것이 하나도 남아 있지 않기 때문이다. 한때 이곳은 스톰윈드의 곡창 지대로서 여러 세대에 걸쳐 젊은 왕국을 먹여 살렸다.\n\n2차 대전쟁 후 스톰윈드를 재건한 석공 조합이 대가를 받지 못하고 경비대마저 그들의 항의에 등을 돌리자, 조합장 에드윈 밴클리프는 바리안 왕의 심판을 받느니 부하들을 이끌고 시골로 숨어들었다. 그곳에서 그들은 데피아스 단이 되었고, 밴클리프는 문브룩의 헛간 아래에서 오래된 광산 갱도를 발견했다. 바다에서 스톰윈드를 불태울 무기를 몰래 만들 수 있을 만큼 깊은 곳이었다. 그는 농부들을 몰아내고, 강발톱 놀을 고용해 땅을 지키게 했으며, 부하들에게 들판을 불태우고 땅에 소금을 뿌려 다시는 아무것도 자라지 못하게 했다.\n\n금고가 바닥난 스톰윈드는 서부 몰락지대가 알아서 살아가도록 내버려 두었다. 오직 그리안 스타우트맨틀만이 나섰고, 아무 군대도 오지 않자 감시의 언덕에서 민병대를 일으켰다.\n\n그가 소금을 뿌린 들판은 그 일로 서부 몰락지대를 용서하지 않았다. 한때 밀이 어깨 높이까지 자라던 곳에서 풀은 여전히 누렇고 가늘게 자란다.",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "저습지",
		short = "댐 아래에는 차갑고 잿빛인 늪지가 펼쳐져 있다. 강과 연못 위로 안개가 깔려 있고, 세 방향은 산에 막혀 있으며 서쪽으로는 바다가 트여 있다.",
		full = "댐 아래에는 차갑고 잿빛인 늪지가 펼쳐져 있다. 강과 연못 위로 안개가 깔려 있고, 세 방향은 산에 막혀 있으며 서쪽으로는 바다가 트여 있다. 곳곳에 흩어진 돌무더기는 한때 이 땅을 지키던 드워프 요새들의 잔해이다. 이제는 멀록과 야수, 변절한 오크들이 대신 이곳을 차지하고 있으며, 메네실 항구만이 이곳에서 얼라이언스의 유일한 진정한 거점이다.\n\n그 항구가 처음부터 얼라이언스의 땅이었던 것은 아니다. 2차 대전쟁이 시작되었을 때, 오그림 둠해머는 바라딘 만의 작은 섬에서 침공 함대를 건조했다. 그의 배들이 지상 방어선을 거치지 않고 로데론 해안을 칠 수 있도록 하기 위해서였다. 그 대가는 저습지가 치렀다. 오크와 용들이 이 땅에서 마구 먹어 치웠고, 사냥감은 줄어들었다. 전쟁이 끝난 뒤 항구는 재건되어 테레나스 메네실 2세를 기려 메네실 항구라는 새 이름을 얻었다.\n\n그림 바톨의 몰락은 그 뒤에 찾아왔다. 그곳에서 용아귀 부족을 섬기도록 노예가 되었던 붉은용군단은 풀려나자마자 포획자들에게 등을 돌렸고, 부족은 무너져 생존자들은 황야로 흩어졌다. 알렉스트라자는 그 산을 봉인해 두는 것이 자신의 용군단이 짊어질 짐이라 여겼고, 그 이후로 붉은용족이 그곳을 지키고 있다.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "텔드랏실",
		short = "말퓨리온 스톰레이지가 에메랄드의 꿈 속으로 사라지자, 대드루이드 판드랄 스테그헬름이 그를 대신해 세나리온 의회를 이끌게 되었고, 고대정령 의회를 설득해 이제 새로운 세계수를 키워 나이트 엘프가 잃어버린 불멸을 되찾을 때가 왔다고 했다.",
		full = "말퓨리온 스톰레이지가 에메랄드의 꿈 속으로 사라지자, 대드루이드 판드랄 스테그헬름이 그를 대신해 세나리온 의회를 이끌게 되었고, 고대정령 의회를 설득해 이제 새로운 세계수를 키워 나이트 엘프가 잃어버린 불멸을 되찾을 때가 왔다고 했다. 그들은 장막의 바다에 대지의 왕관 텔드랏실을 키웠고, 그 가지 위에 다르나서스를 세웠다. 그러나 최초의 세계수를 축복했던 노즈도르무는 이 나무를 축복하길 거부하며 그 소망을 오만이라 일컬었고, 나이트 엘프가 바라던 불멸은 끝내 찾아오지 않았다.\n\n시간이 흐르며 텔드랏실 위의 땅에는 불길한 기운이 드리웠다. 숲의 퍼볼그와 그렐은 미쳐 버렸고, 나무들 사이로 사티로스가 나타났으며, 한때 나무 주변의 바다를 헤엄치던 거대한 거북과 탈곡상어들은 달아나 어둠의 해안 기슭에 올라와 죽었다. 이 타락의 근원은 여전히 수수께끼로 남아 있고, 말퓨리온은 그것을 찾아 나서기 위해 꿈에서 돌아오지 않았다.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "어둠의 해안",
		short = "이 해안에는 잿빛 안개가 드리우지 않는 날이 드물고, 나이트 엘프들은 오래전부터 그것을 경고로 여겨 왔다.",
		full = "이 해안에는 잿빛 안개가 드리우지 않는 날이 드물고, 나이트 엘프들은 오래전부터 그것을 경고로 여겨 왔다. 비와 바위 때문에 이 땅은 살기 좋은 곳이 아니며, 교역소인 아우버다인 너머로 정착하려던 시도는 모두 수포로 돌아갔다.\n\n만 년 전, 이곳에는 아트리쿠스 나라신이 다스리는 쌍둥이 도시 아메스아란과 바샬아란이 서 있었다. 고대의 전쟁이 세계를 부수고 대분리가 닥쳐오자, 아트리쿠스는 백성을 구하겠다고 맹세했다. 그는 약속의 문구는 지켰지만 그 정신은 저버렸다. 그는 영원한 생명이라 속이며 백성의 영혼을 영혼석에 가두었으나, 실은 그들을 빨아들여 자신의 힘을 채웠다. 도시들은 폐허가 되었고, 지금 그 돌무더기 사이를 걷는 것들은 온전히 안식을 얻지 못했다.\n\n3차 대전쟁이 끝난 뒤, 판드랄 스테그헬름은 세나리온 의회의 드루이드들을 어둠의 해안으로 이끌고 와 이 해안에 새로운 세계수 텔드랏실을 심었다.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "잿빛 골짜기",
		short = "잿빛 골짜기는 오래된 나무와 오래된 마법이 가득한 태고의 숲이며, 이 숲을 둘러싼 다툼은 한 번도 멈춘 적이 없다.",
		full = "잿빛 골짜기는 오래된 나무와 오래된 마법이 가득한 태고의 숲이며, 이 숲을 둘러싼 다툼은 한 번도 멈춘 적이 없다.\n\n전쟁노래 부족의 오크들이 처음 이곳에 온 것은 벌목꾼으로서였다. 닐록 그리디핑거가 이끄는 고블린들은 이 지역의 퍼볼그들이 그들을 몰아낼 때까지 나무를 마구 베어 냈고, 그롬마쉬 헬스크림은 고블린의 도움을 잃지 않으려고 퍼볼그와 파수꾼을 차례로 무찔렀다. 세나리우스가 베어진 숲을 되살리려 직접 찾아왔지만, 그 대가는 그의 목숨이었다. 불타는 군단의 지배자들이 그의 믿음을 함정으로 바꾸었고, 그롬마쉬가 그를 쓰러뜨렸다.\n\n군단이 총력을 기울여 잿빛 골짜기로 진군하자 더 끔찍한 일이 뒤따랐다. 아키몬드의 지옥불정령들이 불타며 하늘에서 떨어졌고, 언데드와 악마들이 동쪽에서 휩쓸려 와 분열된 나이트 엘프, 오크, 인간의 군대를 가리지 않고 짓밟은 뒤 하이잘 산으로 밀고 나아갔다. 티란데 위스퍼윈드가 에메랄드의 꿈에서 말퓨리온을 깨웠을 때, 그가 기억하던 숲은 지옥의 불길과 숨 막히는 역병에 삼켜져 있었다.\n\n그 오랜 다툼은 끝나지 않았다. 나이트 엘프들은 여전히 아스트라나르와 흩어진 은신처들을 지키고 있고, 호드는 전쟁노래 부족의 야영지를 남쪽과 동쪽 깊숙이 밀어붙이며 나무를 베고 파수꾼을 밀어내고 있다. 어느 쪽도 이 숲을 둘러싼 싸움을 끝낸 적이 없다.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "버섯구름 봉우리",
		short = "협곡은 깊고 메마르게 뻗어 있고, 그 바닥은 우뚝 솟은 고원들 사이로 사라지다가 동쪽에서 넓은 하늘 아래 펼쳐진 거대한 소금밭, 소금 평원으로 열린다.",
		full = "협곡은 깊고 메마르게 뻗어 있고, 그 바닥은 우뚝 솟은 고원들 사이로 사라지다가 동쪽에서 넓은 하늘 아래 펼쳐진 거대한 소금밭, 소금 평원으로 열린다. 높새바람 봉우리나 먹구름 봉우리 주변 고지대에서 바라보는 일출은 이토록 황량한 땅 위에서 장관을 이룬다. 드루이드 쿠엔틴은 울창한 밀림인 이웃 페랄라스와 바로 맞닿아 있는 이곳의 혹독한 건조함이 자연스러운 것이 아니라, 이 땅에 걸린 어떤 기묘한 마법의 흔적이 아닐까 궁금해했다.\n\n높은 고원들은 타우렌의 땅이며, 높새바람 봉우리는 그 사이에 자리한 그들의 거점이다. 그들이 이 땅을 아무 도전 없이 지켜 온 것은 아니었다. 이 지역의 켄타우로스가 그들을 압박했고, 더 나쁘게도 그림토템 부족의 동족마저 그들에게 등을 돌려, 높새바람 봉우리의 타우렌은 고지대를 두고 부족끼리 싸워야 했다. 그들은 호드의 도움을 받고서야 켄타우로스와 그림토템을 물리칠 수 있었다.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "돌발톱 산맥",
		short = "돌발톱 봉우리는 그 어떤 종족의 것이 되기 전부터 언제나 정령들의 것이었다.",
		full = "돌발톱 봉우리는 그 어떤 종족의 것이 되기 전부터 언제나 정령들의 것이었다. 나이트 엘프는 그 꼭대기에 지하굴과 숲을 두고 자연과 교감하며, 타우렌 또한 이곳을 신성하게 여긴다. 불멸의 예언자가 한때 이곳에서 대지 어머니가 짜는 운명의 실타래를 지켜보았기 때문이다. 전설에 따르면 이 산맥에 처음 정착한 타우렌은 불타는 토템을 들고 가장 높은 바위산까지 올라가 안셰에게 모닥불을 바치며 바위에 달라붙은 어둠을 불살랐다고 한다.\n\n산의 더 낮은 곳에는 엘룬이 오래전 치유의 은총을 내린 샘이 있다. 훗날 하피들이 근처 봉우리를 차지하고 그곳에 둥지를 튼 와이번을 사로잡았으며 샘물을 더럽혔다. 스랄은 케른 블러드후프와 그의 타우렌과 함께 그들에 맞섰고, 켄타우로스 무리를 무찔러 정화의 문양을 얻어 하피들이 오염시킨 것을 깨끗이 했다. 풀려난 와이번들이 그들을 봉우리 꼭대기까지 태워 주었다.\n\n남쪽에서는 그 오랜 대지와의 평화가 사라졌다. 투자개발회사는 칼바람 바위산을 헐벗게 만들었다. 나무를 베고, 공기를 그을음으로 채우고, 물을 기름과 오물로 더럽혔고, 마침내 산의 정령들이 멀리 오그리마의 주술사들까지 들을 만큼 크게 울부짖었다.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "잊혀진 땅",
		short = "바위 어머니 테라제인의 딸 테라드라스는 한때 비옥한 초원 아래에서 잠들어 있었다.",
		full = "바위 어머니 테라제인의 딸 테라드라스는 한때 비옥한 초원 아래에서 잠들어 있었다. 대지 어머니 자신이 그 아래에 산다고 믿은 타우렌 주술사들은 수십 년 동안 그녀를 불렀고, 마침내 무언가가 응답했다. 대지 어머니가 아니라, 잠에서 깨어나 분노한 테라드라스였다. 그녀는 약해진 몸을 되살리려 땅을 집어삼켰고, 초원은 한순간에 죽어 버렸다. 타우렌은 남은 땅을 잊혀진 땅이라 불렀다.\n\n숲의 군주 세나리우스의 아들 자에타르가 그녀를 속박하러 왔지만 오히려 그녀를 사랑하게 되었고, 그녀도 그를 사랑했다. 둘의 결합에서 켄타우로스가 태어났는데, 그들이 처음으로 한 일은 자신들의 아버지를 살해한 것이었다. 그들은 빠르게 번식해 타우렌을 그 땅에서 몰아냈고, 두 종족 사이의 수백 년에 걸친 전쟁이 시작되었다.\n\n테라드라스는 지금도 서쪽 협곡 아래의 마라우돈에 머물고 있으며, 켄타우로스는 바로 그곳에서 자기 종족이 태어났다고 여긴다.",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "페랄라스",
		short = "페랄라스는 이웃한 땅들 사이에서 기이하게 솟아 있다. 주변의 황무지가 오직 흙먼지만을 약속하는 곳에, 태고의 나무들이 우거진 열대 우림이 펼쳐져 있다.",
		full = "페랄라스는 이웃한 땅들 사이에서 기이하게 솟아 있다. 주변의 황무지가 오직 흙먼지만을 약속하는 곳에, 태고의 나무들이 우거진 열대 우림이 펼쳐져 있다. 그 초록 곳곳에는 뿌리와 덩굴에 반쯤 삼켜진 엘프들의 폐허가 흩어져 있으며, 그중 가장 거대한 것은 땅에 묻힌 도시 혈투의 전장이다.\n\n이제 페랄라스는 골두니 오우거의 차지이며, 그들은 이 땅을 부숴 가며 자기 것으로 만들었다. 그들은 숲을 통째로 쓰러뜨렸고, 그들의 오염은 병처럼 땅 위에 내려앉았다. 혈투의 전장 성벽 너머에서 그들의 약탈대는 남쪽 숲 곳곳의 마을을 불태우고 여행자를 살해한다. 황야에 퍼져 가는 이 타락의 뿌리는 그 아래 폐허로 이어진다.\n\n그림토템 타우렌도 여전히 이 지역 곳곳에 흩어져 살고 있으며, 그 부족이 저지른 일을 기억하는 이들에게 쫓기고 있다.",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "먼지진흙 습지대",
		short = "이곳에서는 모기가 멎는 날이 없고, 진흙도 마찬가지다.",
		full = "이곳에서는 모기가 멎는 날이 없고, 진흙도 마찬가지다. 나무들이 물 위로 잎을 너무 빽빽하게 엮어 햇빛은 조각나 내려오며, 바다와 늪이 만나는 짠물 여울에는 악어와 멀록이 도사리고 있다. 남쪽에는 검은용들이 워낙 많이 모여들어 사람들은 그곳을 그저 용의 둥지라 부른다.\n\n이 황무지에 처음으로 진정한 보금자리를 마련한 이는 제이나 프라우드무어였다. 그녀는 하이잘 산 전투가 끝난 뒤 백성을 이끌고 이곳에 와 바위섬 위에 테라모어를 세웠다. 그녀의 도시 성벽은 빛나지만, 그것은 동시에 그녀를 가두고 있다. 불모의 땅으로 향하는 길목의 흩어진 검문소 너머로 늪지는 여전히 거칠고, 그녀의 수비대는 아무도 설명하지 못하는 조용한 탈영으로 점점 줄어들고 있다.\n\n호드와 얼라이언스 사이의 평화가 결정적으로 깨진 곳도 바로 이곳이었다. 대제독 데일린 프라우드무어는 쿨 티라스 함대를 이끌고 늪지에서 호드에 맞섰고, 뒤이은 교전은 그의 죽음으로 끝나 휴전을 공공연한 적대로 굳혀 버렸다.\n\n담쟁이 마을은 돌망치 오우거가 호드에게 문을 열어 준 곳에 서 있다. 그 너머로 불모의 땅으로 가는 길은 텅 빈 채 허물어져 가고 있으며, 언제나 이 땅의 주인이었던 랩터와 거미 말고는 아무도 그 길을 지켜보지 않는다.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "타나리스",
		short = "한때 밀림이 있던 자리를 모래가 채우고 있다. 세계가 부서지기 전 타나리스는 푸른 땅이었고, 구루바시 제국의 영토였다.",
		full = "한때 밀림이 있던 자리를 모래가 채우고 있다. 세계가 부서지기 전 타나리스는 푸른 땅이었고, 구루바시 제국의 영토였다. 대분리가 땅을 찢어 놓자 밀림은 죽었고, 남은 것은 모래 언덕과 바위로 구워졌다. 물이 빠지면서 한 트롤 부족이 이곳에 고립되었고, 이어진 긴 세월 동안 그들의 몸과 삶의 방식은 사막에 맞게 휘어져 더 이상 예전의 트롤이 아니게 되었다. 그들은 모래 트롤, 곧 모래폭풍 부족이 되었다. 자신들을 가둔 땅이 빚어낸 종족이다.\n\n스팀휘들 무역회사의 고블린들은 교역을 위해 이 황무지를 골랐고, 가젯잔과 스팀휘들 항구를 세웠다. 칼림도어에서 그들이 정착할 수 있는 곳 가운데 이 사막이 가라앉은 고향과 가장 닮았기 때문이다. 스팀휘들 항구의 부두는 저 너머의 섬들을 향해 뻗어 있지만, 고블린들은 배를 자기들끼리만 쓰며 다른 종족을 바다 건너로 태워 주려 하지 않는다.\n\n모래 언덕과 남쪽 산맥 아래로는 대부분 지도에 없는 굴이 수십 리에 걸쳐 이어지며, 그 아래로 내려간 이들이 늘 돌아와 무엇을 보았는지 이야기해 주는 것은 아니다.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "아즈샤라",
		short = "아즈샤라는 만 년 동안 가을에 머물러 있다. 나무들은 절벽 위에서 주황과 붉은빛으로 타오르고, 그 절벽은 아직도 한 도시가 잠겨 있는 산호초로 떨어진다.",
		full = "아즈샤라는 만 년 동안 가을에 머물러 있다. 나무들은 절벽 위에서 주황과 붉은빛으로 타오르고, 그 절벽은 아직도 한 도시가 잠겨 있는 산호초로 떨어진다. 아즈샤라는 한때 나이트 엘프가 세운 가장 위대한 대도시였으나, 고대의 전쟁이 닥치자 그 대부분이 바다 속으로 가라앉았다. 부서진 건물 몇 채만이 아직 절벽에 매달린 채 물 아래 자신의 폐허를 내려다보고 있다.\n\n한참 뒤, 일리단 스톰레이지가 나가와 멀구르, 사티로스를 거느리고 하이잘 산에서 북쪽으로 달아날 때, 그는 아즈샤라의 해안을 휩쓸며 나이트 엘프의 항구들을 파괴해 아무도 그를 따라 살게라스의 무덤으로 오지 못하게 했다. 마이에브 섀도송과 그녀의 감시자들이 그 뒤를 쫓아, 그가 지나간 자리에 남긴 광기 어린 괴물들을 처치했다.",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "악령의 숲",
		short = "악령의 숲의 나무들은 자란다기보다 곪아 간다. 껍질에서는 병든 진물이 흘러내리고, 잎은 검게 말려 늘어져 있으며, 그 아래의 짐승들은 흙 속의 타락 때문에 뒤틀리고 굶주린 모습으로 태어난다.",
		full = "악령의 숲의 나무들은 자란다기보다 곪아 간다. 껍질에서는 병든 진물이 흘러내리고, 잎은 검게 말려 늘어져 있으며, 그 아래의 짐승들은 흙 속의 타락 때문에 뒤틀리고 굶주린 모습으로 태어난다.\n\n이 부패는 자연의 우연이 아니었다. 불타는 군단이 하이잘 산으로 밀고 나아갈 때, 아키몬드는 산을 지키는 나이트 엘프를 약화시키기 위해 숲을 망가뜨리라 명령했고, 공포의 군주 티콘드리우스가 끔찍한 힘을 지닌 흑마법사의 유물인 굴단의 해골로 그 명령을 수행했다. 땅은 안에서부터 죽어 가는 것으로 응답했다. 고대정령들은 썩어 난폭해졌고, 짐승들은 변이했으며, 대지 자체가 독에 물들었다.\n\n일리단 스톰레이지가 남은 생을 결정지은 선택을 한 곳도 바로 이곳이었다. 해골의 힘으로 그것이 일으킨 타락에 맞설 수 있다는 말을 들은 일리단은 홀로 악령의 숲으로 들어가 티콘드리우스를 베고 그 유물을 차지했다. 그는 그 뒤에도 유물을 내놓지 않았다. 마법에 대한 갈망이 신중함보다 강했던 것이다. 군단의 힘을 사용한 대가로, 그는 친형 말퓨리온에게 추방당했다.",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "운고로 분화구",
		short = "운고로 분화구는 세 사막 사이에 벽처럼 막힌 채 칼림도어 남부에 움푹 들어앉은 초록빛 상처이며, 이곳에서 세상은 황량해야 한다는 것을 잊는다.",
		full = "운고로 분화구는 세 사막 사이에 벽처럼 막힌 채 칼림도어 남부에 움푹 들어앉은 초록빛 상처이며, 이곳에서 세상은 황량해야 한다는 것을 잊는다. 기억보다도 오래된 공룡들이 밀림을 누비는데, 그중 일부는 살아 있는 어떤 것도 이르러서는 안 될 크기로 자랐고, 대지와 불의 정령들이 그들 사이를 아무렇지 않게 걸어 다닌다. 그 위의 능선에는 아무도 설명한 적 없는 수정탑들이 서 있다.\n\n흐르는 모래의 전쟁 때 나이트 엘프들은 이 분화구를 지나 타나리스 사막 끝자락까지 밀려났고, 바로 그곳에서 퀴라지의 진격이 꺾였다. 운고로 자체의 무언가가 침략자들이 이 땅을 차지하도록 허락하지 않았지만, 그것이 무엇인지는 아무도 말하지 않았다.\n\n윌리든 마샬과 홀아니 마샬이 이끈 원정대가 한때 이곳에 거점을 마련하려 했지만, 분화구의 야만성은 그들이 대비한 것 이상이었다. 야영지는 짓밟혔고, 생존자들은 더 높은 곳으로 달아나 지금은 마샬의 야영지라 불리는 곳에서 최후의 저항을 벌였다.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "달의 숲",
		short = "달의 숲은 산으로 둘러싸인 고리 안에 포근히 안긴 숨겨진 골짜기로, 이곳의 숲은 한 번도 타락을 겪은 적이 없다.",
		full = "달의 숲은 산으로 둘러싸인 고리 안에 포근히 안긴 숨겨진 골짜기로, 이곳의 숲은 한 번도 타락을 겪은 적이 없다. 그 중심에는 여신의 이름을 딴 엘룬아라 호수가 있고, 호숫가의 나이트헤이븐 마을에서는 타우렌과 나이트 엘프가 다툼 없이 함께 거닌다. 그들은 자연에 대한 공통된 경외로 묶여 있으며, 달의 숲 수호자들은 그 유대가 깨지는 것을 결코 용납하지 않는다.\n\n고대의 전쟁 시절, 나이트 엘프가 군단 앞에서 파멸의 벼랑 끝에 섰을 때 말퓨리온 스톰레이지가 찾아온 곳이 바로 이 골짜기였다. 말퓨리온은 자기 동족이 홀로는 이길 수 없음을 알았고, 티란데 위스퍼윈드와 동생 일리단을 이끌고 달의 숲의 성스러운 고요 속으로 들어가 세나리우스에게 도움을 간청했다. 반신은 응답했고, 대분리가 세계를 새로 빚은 뒤 숲의 수호자들과 이곳에 몸을 피했던 드라이어드들은 세상으로 나아갔다. 세나리우스 자신은 결코 떠나지 않았고, 달의 숲은 드루이드 신앙의 가장 신성한 땅이 되었다.\n\n셀 수 없이 많은 둔덕 아래에는 옛 드루이드들의 성소가 잠들어 있고, 엘룬아라 호수 아래에는 한때 엘룬의 사랑을 받았던 반신 오멘이 편치 않은 잠에 빠져 있다.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "실리더스",
		short = "이 사막은 칼림도어의 남서쪽 끝자락에 자리한 부서진 바위와 모래의 황무지로, 운고로에서 뻗어 나온 넓은 길을 따라 닿을 수 있다.",
		full = "이 사막은 칼림도어의 남서쪽 끝자락에 자리한 부서진 바위와 모래의 황무지로, 운고로에서 뻗어 나온 넓은 길을 따라 닿을 수 있다. 그 지하에는 아퀴르 제국의 잔재인 안퀴라즈가 있다. 나이트 엘프는 무언가 끔찍한 것이 깨어나지 못하도록 그 중앙 사원을 봉인했다. 실리더스 곳곳에 흩어진 폐허와 지금 모래 속에 벌집처럼 뚫린 실리시드 둥지들은 그 봉인이 버티지 못했다는 충분한 증거이다.\n\n오래전 퀴라지는 흐르는 모래의 전쟁이 끝난 뒤 스카라베 성벽 뒤로 쫓겨나 그곳에 갇혔다. 그들의 하수인인 실리시드는 풀려난 채 남았고, 수 세기에 걸쳐 번식하며 칼림도어 남부 전역으로 퍼져 나갔다. 마침내 나이트 엘프는 그 위협이 더 이상 지켜보기만 할 수 없을 만큼 커졌다고 판단했고, 대신 안퀴라즈 성문을 다시 열어 성벽이 미루어 두었을 뿐인 일을 끝내기로 했다.\n\n세나리온 의회는 세나리온 요새에서 감시를 계속하며 실리시드 무리를 추적하고, 그것이 어느 한 종족이 홀로 맞서기에는 너무 큰 위험인지 가늠하고 있다.",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "여명의 설원",
		short = "여명의 설원에는 눈이 끊임없이 덮여 있으며, 악마들이 남쪽 지역을 휩쓴 곳에서조차 그 아름다움은 흐트러지지 않았다. 한때 이곳은 말리고스의 배우자 할레를 비롯한 많은 푸른용군단의 보금자리였다.",
		full = "여명의 설원에는 눈이 끊임없이 덮여 있으며, 악마들이 남쪽 지역을 휩쓴 곳에서조차 그 아름다움은 흐트러지지 않았다. 한때 이곳은 말리고스의 배우자 할레를 비롯한 많은 푸른용군단의 보금자리였다.\n\n만 년 전 명가는 엘다라스의 한 신전에서 진말로의 수정을 훔친 뒤 이곳에 켈테릴이라는 도시를 세웠다. 그들은 수정의 힘을 시험해 보고 싶은 유혹을 이기지 못했고, 수정이 산산이 부서지자 그로부터 풀려난 저주가 그들을 집어삼켰다. 수정이 시작한 일을 대분리가 마무리했고, 켈테릴은 폐허가 되었다. 그곳의 망자들은 결코 떠나지 않았다. 훗날 수정의 파편을 찾아 쿠엘탈라스에서 하이 엘프들이 왔지만, 같은 광기가 그들도 사로잡았다. 이제 그들의 유령은 자신들이 연구하러 왔던 망자들과 나란히 폐허를 떠돈다.\n\n골짜기의 중심인 눈망루 마을은 고블린들이 차지하고 있고, 나이트 엘프들도 여전히 이곳에서 나름의 감시를 이어 가며 그 둘보다 오래된 고향을 지키고 있다.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "스톰윈드",
		short = "오크 호드가 불태운 뒤, 스톰윈드는 젊은 바리안 왕의 치세 아래 석공 조합의 손으로 하얀 돌의 도시로 다시 일어섰다.",
		full = "오크 호드가 불태운 뒤, 스톰윈드는 젊은 바리안 왕의 치세 아래 석공 조합의 손으로 하얀 돌의 도시로 다시 일어섰다. 그러나 전쟁 빚으로 왕실 금고가 바닥나고 귀족들이 조합에 품삯을 주지 않자, 조합장 에드윈 밴클리프의 항의에 돌아온 것은 조합의 해산이었다. 폭동이 뒤따랐고, 그 혼란 속에서 티핀 린 왕비가 목숨을 잃었다. 바리안의 분노는 석공들을 서부 몰락지대로 내쫓았고, 그들은 그곳에서 데피아스 단이 되었다. 그동안 왕좌 뒤에서는 카트라나 프레스터라는 고문이 자신의 목적을 위해 은밀히 왕과 조합을 이간질했다.\n\n그 후 바리안 왕은 수상한 정황 속에 실종되었고, 프레스터 부인의 권유에 따라 왕국의 질서를 지키기 위해 왕관은 그의 어린 아들 안두인 왕자에게 넘어갔다. 대영주 볼바르 폴드라곤이 스톰윈드의 섭정이자 군 사령관으로 봉직하고, 프레스터 부인은 왕국의 자원을 어떻게 쓸지 그에게 조언한다. 성 안에서 그녀를 의심하거나 그녀에게 맞서는 이는 아무도 없다.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "오그리마",
		short = "오그리마는 하이잘 산 전투 이후, 대족장 스랄이 동족을 이끌고 칼림도어의 황량한 해안에 왔던 시절에 세워졌다.",
		full = "오그리마는 하이잘 산 전투 이후, 대족장 스랄이 동족을 이끌고 칼림도어의 황량한 해안에 왔던 시절에 세워졌다. 그는 아버지를 기려 그 땅을 듀로타라 불렀고, 그곳에 세운 도시는 자신을 길러 준 벗이자 스승인 오그림 둠해머를 기려 오그리마라 이름 지었다. 도시는 빠르게 세워졌지만 허술하지 않았다. 튼튼한 성벽과 거대한 성문, 높은 탑을 갖추었고, 뒤편의 산을 깎아 요새의 일부로 삼아 대지가 도시를 지키도록 했다.\n\n도시를 세운 호드는 한때 세상을 불태우며 휩쓸었던 그 호드가 아니었다. 악마의 저주가 풀리자 스랄의 백성은 정복이 아닌 생존을 향해 돌아섰고, 오그리마는 오크만큼이나 다른 이들의 손으로 세워졌다. 고블린과 타우렌, 검은창 트롤이 그들과 함께 일했고, 모크나탈의 렉사르도 일손을 보탰다. 켄타우로스와 하피, 천둥도마뱀, 코볼트, 가시멧돼지가 모두 첫 몇 해 동안 이 젊은 도시를 시험했지만, 도시는 버텨 냈다. 그리고 오크뿐 아니라 트롤과 타우렌, 시간이 흘러서는 새로 호드에 받아들여진 포세이큰의 보금자리가 되었다.\n\n이곳에서는 바람조차 친구가 아니다. 칼날 같은 바람이 골짜기를 휩쓸며, 허술하게 지은 건물의 지붕쯤은 뜯어낼 만큼 거세게 분다.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "아이언포지",
		short = "아이언포지는 드워프의 수도로, 드워프의 조상 대대로의 고향인 던 모로 북부 아이언포지 산 깊숙이 새겨져 있으며, 아제로스에서 가장 오래된 도시 가운데 하나이다.",
		full = "아이언포지는 드워프의 수도로, 드워프의 조상 대대로의 고향인 던 모로 북부 아이언포지 산 깊숙이 새겨져 있으며, 아제로스에서 가장 오래된 도시 가운데 하나이다. 이곳은 카즈 모단의 수도이며, 브론즈비어드 부족의 마그니 브론즈비어드 왕이 다스린다.\n\n장인과 탐험가, 광부와 전사의 거대한 지하 도시인 아이언포지는 그 산업과 얼라이언스 교역의 중심지로 이름이 높으며, 요새이자 수도로서 드워프의 힘과 강인함을 보여 주는 증거이다. 도시는 동심원 모양의 고리들로 이루어져 있고, 지하 깊이 내려갈수록 층이 작아지며, 그 모두가 중앙에 있는 도시 이름의 유래인 대용광로에서 뻗어 나간다. 좁은 통로와 바위벽을 파서 만든 상점, 동굴 같은 방들이 가득하다. 이곳은 북적이고 시끌벅적하며 공업 도시의 느낌이 나지만 아늑하기도 하다. 여관과 상점의 화로에서는 불길이 으르렁거리고, 드워프들의 웃음소리와 흥겨운 소란이 끊이지 않는다. 스톰윈드나 다르나서스와 달리 이 도시는 드워프들이 직접 땅속에 파낸 거대한 동굴이며, 천장과 바닥 모두 단단한 바위로 되어 있다.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "썬더 블러프",
		short = "썬더 블러프는 멀고어의 초원 위, 바람이 휘몰아치는 네 개의 고원 위에 솟아 있으며, 타우렌이 만든 밧줄과 나무 승강기나 고원 사이에 걸린 긴 다리로만 오갈 수 있다.",
		full = "썬더 블러프는 멀고어의 초원 위, 바람이 휘몰아치는 네 개의 고원 위에 솟아 있으며, 타우렌이 만든 밧줄과 나무 승강기나 고원 사이에 걸린 긴 다리로만 오갈 수 있다. 봉우리마다 천막과 긴 집, 채색된 토템이 얹혀 있다. 여러 세대 동안 타우렌은 칼림도어 곳곳을 누비는 켄타우로스에게 쉼 없이 시달리며 떠도는 유목민으로 살았다. 그 유랑을 끝낸 이는 블러드후프 부족의 족장 케른 블러드후프였다. 3차 대전쟁 때 대족장 스랄과 그의 새로운 호드가 멀고어에 왔을 때, 그들의 힘은 케른의 힘과 하나가 되었고, 그들은 함께 켄타우로스를 무찔러 마침내 타우렌에게 초원을 안겨 주었다. 케른은 고원 위에 흩어진 모든 부족에게 열린 안식처를 세웠고, 시간이 흘러 그 부족들은 한 민족으로서 그의 통치를 따르게 되었다. 앞으로 나아갈 길에 대해서는 때때로 의견이 갈렸지만, 그들을 이끄는 그의 지혜에 대해서는 결코 이견이 없었다.\n\n고원들은 그 솟은 봉우리와 다리에, 그리고 한 족장의 지붕 아래 모인 부족들의 천막에 지금도 그 건국의 무게를 짊어지고 있다.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "다르나서스",
		short = "나이트 엘프는 3차 대전쟁 이후, 그들의 오랜 불멸이 사라졌을 때 다르나서스를 세웠다. 많은 이들이 갑작스레 찾아온 노화와 나약함의 무게를 견디지 못했다.",
		full = "나이트 엘프는 3차 대전쟁 이후, 그들의 오랜 불멸이 사라졌을 때 다르나서스를 세웠다. 많은 이들이 갑작스레 찾아온 노화와 나약함의 무게를 견디지 못했다. 슬픔에 잠긴 드루이드 몇몇은 영원한 세계와의 유대를 되찾기 위해 새로운 세계수를 심기로 결심했다. 말퓨리온 스톰레이지가 실종되자, 판드랄 스테그헬름이 대드루이드의 자리를 이어받아 그 일을 이끌었다. 그들이 키운 나무 텔드랏실은 해안에서 솟아올라 그 꼭대기가 구름을 뚫었고, 나이트 엘프는 그 가지 사이에 동족이 살아남았음을 증명하는 도시를 세웠다.\n\n다르나서스는 인간과 드워프의 비좁고 성벽에 둘러싸인 도시들과 달리 하늘을 향해 열려 있다. 도시는 넓은 호수를 둘러싸고 세워졌으며, 호숫가는 우아한 다리로 이어져 있고, 길에는 낙엽이 양탄자처럼 깔려 있다. 달의 신전은 대여사제 티란데 위스퍼윈드와 엘룬의 자매단의 본거지로서 나무들 위로 솟아 있고, 그 곁에는 파수꾼들이 감시를 서는 열주가 늘어선 정의의 전당이 있다. 도시는 처음 세워진 목적 그대로 남아 있다. 평온한 안식처이자, 필멸과 함께 사는 법을 배워 가는 한 종족의 기념비로서.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "언더시티",
		short = "포세이큰이 차지하기 훨씬 전부터 언더시티에는 이름과 쓰임새가 있었다. 로데론 궁전 저 아래로는 왕실 망자들의 오래된 납골당과 지하 감옥, 하수도가 뻗어 있었다.",
		full = "포세이큰이 차지하기 훨씬 전부터 언더시티에는 이름과 쓰임새가 있었다. 로데론 궁전 저 아래로는 왕실 망자들의 오래된 납골당과 지하 감옥, 하수도가 뻗어 있었다. 그곳은 오직 죄수와 시체를 위한 곳이었지만, 로데론에서 가장 가난한 사람들은 어떻게든 그 어둠 속으로 몰려들었고, 그들을 몰아내려는 경비병들의 소탕은 한 번도 효과를 거두지 못했다.\n\n리치 왕이 자신의 피조물에 대한 장악력을 잃자, 실바나스 윈드러너는 정신을 유지한 언데드들과 함께 스컬지에서 떨어져 나와, 자신을 이렇게 만든 타락한 왕자 아서스에게 칼끝을 돌렸다. 그녀는 폐허가 된 왕국에서 그를 함정으로 꾀어냈지만, 그는 켈투자드의 도움으로 빠져나가 북쪽으로 달아나 스스로 리치 왕이 되었다. 싸움터의 주인으로 남은 실바나스와 그녀의 추종자들은 스스로를 포세이큰이라 부르며 폐허가 된 수도 아래의 납골당을 차지했고, 스컬지가 짓기 시작한 요새를 완성했다.\n\n지금 서 있는 것은 방어를 위해 지은 미로이다. 모든 길을 따라 독성 오물의 강이 흐르고, 공기는 산 자가 숨쉬기도 힘들 만큼 짙은 독기로 가득하다. 포세이큰에게 그곳은 여전히 자신들을 사냥하는 세상 속의 피난처이다.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
}

